import sys

def solve():
    n, x = map(int, input().split())
    a = list(map(int, input().split()))

    def rec(i):
        if i == 0:
            return a[0]
        else:
            return max(rec(i-1), a[i] - a[i-1])

    res1 = rec(n-1)
    res2 = x - a[-1] + max(a[-1] - x, 0)

    if res2 < 0: 
        res2 = 0
    sys.stdout.write(str(max(res1, res2)*2)+'\n')

def solve():
    """
    Calculates the minimum possible volume of the gas tank in the car that will allow it to travel from point 0 to point x and back.

    :return: The minimum required volume of the gas tank.
    """

    # Read input values (number of stations, distance x) ensuring they are numeric
    try:
        n, x = map(int, input().split())
    except ValueError:
        print("Invalid input. Both number of stations and distance must be integers.")
        return

    if not isinstance(n, int) or not isinstance(x, int):
        raise TypeError("Input data types are not recognized.")

    # Attempt to read the station array 'a' - it's expected to contain n elements representing distances between stations
    try:
        a = list(map(int, input().split()))

        if len(a) != n:
            print("Invalid number of stations provided.")
            return

        for i in range(len(a)):
            if not isinstance(a[i], int):
                raise TypeError("All station values must be integers.")

    except ValueError:
        print("Error reading station distances. Please ensure these are numeric and separated by spaces.")
        return

    # Define the recursive function to calculate maximum distance covered so far at each step
    def max_distance_covered(stations, remaining):
        if not stations or remaining < 0:  
            # Base case for recursion termination when no more stations are left or invalid number of steps provided
            return -1  

        max_dist = float('-inf')  

        next_distances = [(stations[i], i) for i in range(len(stations)) if stations[i] >= 0]

        # Check for scenarios where station list might have inconsistent data
        if not next_distances:
            raise Exception("Inconsistent input: all station distances seem to be non-positive.")

        max_dist = max(max_dist, max_distance_covered(next_distances[:-1], remaining - 1))

        return max_dist

    res = max_distance_covered(a, n)

    if res == float('-inf'):
        raise Exception("Could not find a distance for the provided inputs.")

    # Further processing based on the maximum allowed distance might be necessary according to problem constraints
    print(res)

