import sys

def I(): return input().rstrip()
def II(): return int(input().rstrip())
def MII(): return map(int, input().rstrip().split())

def solve():
    n, c = MII()
    s = I()

    def check(index):
        if index + c > len(s): 
            return False

        return sum(1 for j in range(index) if s[j] == "B") + (len(s)-c-index).count('B') >= c

    res = []

    for i in range(len(s)):
        if check(i):
            res.append([i+1, 'A'])
            break
    else:
        return 0, None

    if sum(1 for j in range(n) if s[j] == "B") < c: 
        res.append([s.rfind('A')+1,'B'])

    return len(res), res

