import sys

def solve():
    input_data = input().rstrip()
    test_cases = int(input_data)

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, min(int(math.sqrt(n))+1, n)):
            if n % i == 0:
                return False
        return True

    results = []
    for _ in range(test_cases):
        string_data = input().rstrip()
        input_list = list(map(int, string_data.split(' ')))

        count = 0

        def compute(num_list):
            nonlocal count

            # Loop invariant check and updates
            if not num_list:
                return True
            elif is_prime(num_list[-1]):
                num_list.pop()
                count += len(num_list)
                compute(num_list)

        final_result = f"{count}" if compute(input_list) else "NO"

        results.append(final_result)

    for result in results:
        print(result)

import sys

def solve():
    n, k = map(int, input().split())
    s = list(input().strip())

    count_of_bs = s.count('B')

    if k == count_of_bs:
        return "0"
    elif k > count_of_bs:
        index_to_change = 0
        max_no_of_changes = -sys.maxsize - 1

        for i in range(n):
            if s[i] == 'A':
                no_of_moves = (i + 1) - count_of_bs

                if no_of_moves > max_no_of_changes and k >= (count_of_bs + no_of_moves):
                    index_to_change = i + 1
                    max_no_of_changes = no_of_moves

        return str(1) + '\n' + str(index_to_change) + ' B'
    else:
        j1 = -1

        for i in range(n):
            if s[i] == 'B':
                count_of_bs -= 1

                if count_of_bs == k:
                    j1 = i
                    break

        return str(1) + '\n' + str(j1 + 1) + ' A'

