    nums = sorted(nums)

    q1, q2 = deque(), deque()
    for i in range(n):
        q1.append((nums[i], 0))
        q2.appendleft((nums[n+i], 0))

    dists = []
    res = []
    idx = -1

    while q1:
        temp_x, temp_y = 0, 0
        min_dist = 10 ** 9

        for _ in range(4):
            x, y = (-1,-1),(-1,-1)

            if q2: 
                x = q2[0]
            if q1:
                y = q1[0] if len(res) == idx else (q1[-1] if res else q1[0])   

            dist = abs(temp_x - x[0]) + abs(temp_y - x[1]) if x != (-1,-1) and len(dists)%2==0\
                else abs(temp_x - y[0]) + abs(temp_y- y[1])

            if min_dist > dist:
                idx, min_dist = (_+len(res))%4, dist

        if res:  
            dists.append(min_dist)

        if (idx)%2==1 or not q2 or not q1:
            a = q1.popleft()
            temp_x, temp_y = a[0],a[1]
            idx %= 2
        else:
            a = q2.popleft()
            temp_x, temp_y = a[0], a[1]

        res.append(a)

    print(sum(dists))

    for x,y in res:        
