import math

def check(seq):
    return all(x <= y for x, y in zip(seq, seq[1:]))

def recurse(l, n, pow_of_2, threshold):
    if not l:
        return True

    head = l[:pow_of_2]
    tail = l[pow_of_2:]

    for i in range(threshold + 1):
        new_head = [x - i for x in head]
        if check(recurse(tail, n, pow_of_2 // 2, i) and new_head): 
            return True

    return False

