import sys
def solve():
    n = int(input().strip())
    arr = list(map(int, input().split()))
    count = Counter(arr)

    # check if array can be rearranged into a sequence with equal sums of adjacent elements
    max_count = (n + 1) // 2
    if len(count) == 1:
        return True
    elif len(count) > 2:
        return False
    else:
        min_val, max_val = sorted(count.keys())
        min_cnt, max_cnt = count[min_val], count[max_val]

        # rearrangement is possible when one pair of numbers has the same sum as all other pairs
        if (min_cnt == 1 and max_cnt <= max_count) or (max_cnt == 1 and min_cnt <= max_count):
            return True
        elif abs(min_cnt - max_cnt) <= 1:
            return True
        else: 
            return False

