from typing import List

def solve(n: int, k: int, arr: List[int]) -> str:
    def check_subsegment(arr, target):
        count_dict = {}
        for num in arr:
            if num not in count_dict:
                count_dict[num] = 1
            else:
                count_dict[num] += 1
            max_count = max(count_dict.values())
            most_common_element = [key for key, value in count_dict.items() if value == max_count]
            if target in most_common_element and len(most_common_element) == 1:
                return True
        return False

    return "YES" if check_subsegment(arr, k) else "NO"

