import math

def solve(targets):
    scores = []
    for target in targets:
        score = 0
        for i, row in enumerate(target):
            for j, cell in enumerate(row):
                distance = math.sqrt((i - 4.5) ** 2 + (j - 4.5) ** 2)
                ring = max(math.floor(5 - distance), 1)
                if cell == 'X':
                    score += min(ring, 5)
        scores.append(str(score))
    return "\n".join(scores)

