from typing import List

def solve() -> int:
    n = int(input()) # Number of integers in list

    a_str = input().split()

    if len(a_str) != n:
        raise ValueError("Length of input doesn't match the provided count")

    try:
        a = list(map(int, a_str))
    except ValueError as e:
        print(f"Invalid integer value found: {e}")
        return None

    if min(a) < 0:
        print("Warning: Negative number encountered. Functionality not well-defined.")

    # Find index of smallest element and add 1 to it
    min_val_idx = a.index(min(a)) 
    a[min_val_idx] += 1 

    return functools.reduce(operator.mul, a, 1)

