def solve():
    x, y, n = map(int, input().split())

    if (y - x) < (n * (n - 1)) // 2:
        return [-1]

    result = [y - i*(i + 1)//2 for i in range(n-1)]
    if result[0] <= x:
        result.insert(0, x)
    else:
        result = [x] + result
        diff = (result[1] - result[0]) // 2
        result = [result[0]] + [result[i] + diff for i in range(1, len(result))]

    return result

