def solve():
	inp = lambda: input().strip()
	n, initial_online, _ = map(int, inp().split())
	s = inp()


	currently_online = initial_online
	offline_subscribers = n - initial_online
	guaranteed_offline = False


	for c in s:
		if c == '+':
			currently_online += 1
			if offline_subscribers > 0:
				offline_subscribers -= 1
			if currently_online == n: break
		else:
			currently_online -= 1
			if not guaranteed_offline and currently_online < n:
				guaranteed_offline = True


	if guaranteed_offline:
		return "NO"
	elif currently_online == n:
		return "YES"
	else:
		return "MAYBE"

