def solve():
    input_data = [x[0] for x in sys.stdin.buffer.read().splitlines()[::-1]]

    def _next_token():
        nonlocal input_data
        return input_data.pop()

    t = int(_next_token())
    res = []

    while t > 0:
        n, m = map(int, _next_token().split(' '))

        carpet = [_next_token() for _ in range(n)]
        vika_idx = ["v","i","k","a"]
        cur_idx = 0

        cols = []
        for col in zip(*carpet):
            cols.append("".join(col))

        for col in cols:
            is_ = vika_idx[cur_idx] in col
            if is_: 
                cur_idx += 1

            if cur_idx >= len(vika_idx): break  

        res.append("YES" if cur_idx >= len(vika_idx) else "NO")

        t -= 1

    return '\n'.join(res)

