import itertools

def solve(n, arr):
    # Generate all possible combinations of two colors (0 and 1)
    combos = list(itertools.product([0, 1], repeat=n))

    # Iterate over each combination
    for combo in combos:
        # Initialize sums for both colors
        sum_0, sum_1 = 0, 0

        # Partition the array into two groups based on the current color combination
        for i, x in enumerate(arr):
            if combo[i] == 0:
                sum_0 += x
            else:
                sum_1 += x

        # Check if both colors have at least one element and their sums have the same parity
        if sum_0 != 0 and sum_1 != 0 and not (sum_0 % 2) ^ (sum_1 % 2):
            return "YES"

    # If no valid coloring is found, return "NO"
    return "NO"

