import sys

def solve():
    readline = sys.stdin.readline

    def readIntLine():
        return [int(w) for w in readline().split()]

    t = int(readline())

    answers = []
    for _ in range(t):
        n = int(readline())
        a = readIntLine()

        max_prefix_len = [0] * n
        maxprefixlen = 0
        for i, v in enumerate(a):
            if i == 0 or v >= a[i - 1]:
                maxprefixlen += 1
            else:
                max_prefix_len[i - 1] = maxprefixlen
                maxprefixlen = 0

        max_prefix_len[-1] = max(maxprefixlen, max_prefix_len[-1])

        suffix_maxes = [0] * n
        suffmax = a[-1]
        for j in range(n-2,-1,-1):
            if a[j]>suffmax:
                suffix_maxes[j]=a[j]
                suffmax=a[j]
            else:
                suffix_maxes[j] = max(suffix_maxes[j+1],a[j])

        unsorted_pairs_start_with = 0
        while unsorted_pairs_start_with<n-1 and a[unsorted_pairs_start_with]<=a[unsorted_pairs_start_with+1]:
            unsorted_pairs_start_with += 1

        diff=0
        for i in range(unsorted_pairs_start_with,n-1):
            if max_prefix_len[i] > suffix_maxes[i + 1]:
                diff = suffix_maxes[i + 1] - a[i]

                break

        answers.append(diff)

    return "\n".join(map(str,answers))

