import heapq

def solve():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    if k == 1:
        return sum(abs(a[i+1] - a[i]) for i in range(n-1))

    heap = []
    total_sum = 0
    for diff in (abs(x - y) for x, y in zip(a, a[1:])):
        total_sum += diff
        heapq.heappush(heap, -diff)

    while k > 1 and heap:
        top_diff = -heapq.heappop(heap)
        total_sum -= top_diff * 2
        k -= 1

    return max(total_sum, 0)

