def mex(a):
    """Calculates the minimum excluded value."""
    n = len(a)
    b = [0]*n
    for i in a:
        if i < n:
            b[i] += 1
    ans = 0
    while ans < n and b[ans] > 0:
        ans += 1
    return ans

def is_prime(n):
    """Checks if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

