from math import log

def solve(n):
    levels = int(log(n // 2 + 1, 2)) if n > 3 else 0
    start_point = max(0, n - (1 << levels-1) - ((1 << levels-1)-1))
    sum_val = ((n + start_point) * (levels+1)) 

    last_level_sum = ((n-start_point+1)*(start_point//2*3+(n-start_point)+(n-start_point)//4))
    if n % 2**levels == 0 and n > 3:
        sum_val -= last_level_sum

    return int(1 + sum_val)

