def solve():
    try:
        # Read the number of elements (n) from stdin and validate that it's a positive integer.
        n = int(input().strip())

        if n <= 0:
            print("Invalid input. Please enter a positive integer.")
            return None

        # Read 'n' elements, ensure they're integers, sort in ascending order, then calculate the total cost.
        try:
            # Split the next line into individual numbers and convert them to integers
            numbers = list(map(int, input().split()))

            if len(numbers) != n:
                print("Invalid input. Mismatch between specified count 'n' and actual number of elements provided.")
                return None

        except ValueError:
            print("Invalid input. Please ensure all elements are integers.")
            return None

        # Sort the numbers in ascending order
        numbers.sort()

        # Calculate the total cost by pairing up elements from both ends (maximizing the difference)
        total_cost = sum(max(numbers[i], numbers[n - i - 1]) - min(numbers[i], numbers[n - i - 1]) 
                         for i in range(n // 2))

        # If 'n' is odd, add the middle element once to account for its contribution
        if n % 2 != 0:
            total_cost += numbers[n // 2]

        return total_cost

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None

