from functools import lru_cache

def solve():
    n = int(input())

    @lru_cache(None)
    def dp(x):
        if x < 5:
            return "Bob"  # Alice loses, so Bob wins
        elif 5 <= x <= 10:
            return "Alice"  # Base case for recursive calls
        else:
            result = dp(dp(x-5))  # Recursive call to flip the outcome
            if result == "Alice":
                return "Bob"  # Flip the winner if Alice was going to win
            else:
                return "Alice"

    outcome = dp(n)
    print(outcome)  # Print the final result

