from collections import Counter

def solve():
    n = int(input())
    nums = list(map(int, input().split()))
    count = Counter(nums)

    # Get counts of -1 and 1 in the array.
    neg_count = count[-1]
    pos_count = count[1]

    diff = abs(neg_count - pos_count)

    if diff % 2 == 0: 
        return min(diff // 2 + (neg_count > pos_count), n - diff)

    elif diff <= 4:
        # Handle edge cases when the array only contains one or two elements.
        return min(abs(pos_count - neg_count), 1) 

    elif diff % 4 == 0: 
        # Return minimum when difference is divisible by 4 and greater than or equal to 8.  
        operations = ((diff // 2) * 2) // 4
        remaining_elements = n - diff

        return min(operations, remaining_elements)

    elif (diff - 1) % 4 == 0:
        # Handle case when the difference is one more than a multiple of four and greater than or equal to 8.
        operations = ((diff // 2) * 2) // 4 
        return min(operations + 2, n)

    else:  
        # General minimum operation computation for the case where diff % 2 !=0 and difference is not divisible by four.
        operations_1_diff = ((pos_count - (neg_count))**2)//4  

        if pos_count > neg_count:
            return min(operations_1_diff, n)

        else: 
            remaining_elements_count = n - abs(pos_count - neg_count) 
            return min(operations_1_diff, remaining_elements_count)

