def solve():
    import heapq

    # Read input values
    n = int(input())

    # Initialize maps for skill-time combinations
    time_map_01, time_map_10, time_map_11 = [], [], []

    # Populate the time maps with input data
    for _ in range(n):
        time, skills = input().split()
        if skills == "01":
            heapq.heappush(time_map_01, int(time))
        elif skills == "10":
            heapq.heappush(time_map_10, int(time))
        else:
            heapq.heappush(time_map_11, int(time))

    # Handle special cases
    min_time = float('inf')

    # Calculate the minimum time with at least one full skill book (both skills in a single book)
    if len(time_map_11) > 0:
        min_time = heapq.heappop(time_map_11)
        while len(time_map_11) > 0 and time_map_11[0] == min_time:
            heapq.heappop(time_map_11)

    # Calculate the minimum time when acquiring skills from separate books
    if len(time_map_01) > 0 or len(time_map_10) > 0:
        additional_time = float('inf')
        if len(time_map_10) > 0 and (len(time_map_01) == 0 or time_map_10[0] < time_map_01[0]):
            heapq.heappop(time_map_10)
            if len(time_map_11) > 1:
                additional_time = min(additional_time, -time_map_10[0])
        elif len(time_map_01) > 0 and (len(time_map_10) == 0 or time_map_01[0] < time_map_10[0]):
            heapq.heappop(time_map_01)
            if len(time_map_11) > 1:
                additional_time = min(additional_time, -time_map_01[0])
        if len(time_map_10) > 0 and len(time_map_01) > 0:
            additional_time = min(additional_time, time_map_01[0] + time_map_10[0]) if len(time_map_11) == 1 else min(min(time_map_10), min(time_map_01))
        elif len(time_map_10) > 0:
            additional_time = min(additional_time, -time_map_10[0]) if len(time_map_11) > 1 else time_map_10[0]
        elif len(time_map_01) > 0:
            additional_time = min(additional_time, -time_map_01[0]) if len(time_map_11) > 1 else time_map_01[0]

    # Return the overall minimum time
    print(min(min_time, additional_time))

