import math

def solve(s):
    length = len(s)
    mid_index = 1 + (length - 1) // 2 if length % 2 == 0 else (length+1) // 2

    def remove_char_at(pos, string=s):
        return s[:pos-1] + s[pos:]

    for pos in range(1, mid_index+1):
        without_pos = remove_char_at(pos)

        left_equals_right_half = without_pos[:math.ceil(length/2)] == without_pos[math.floor(length / 2):][::-1]
        if not left_equals_right_half:
            return len(without_pos)

    return -1

