import math

def solve():
    try:
        n, k = map(int, input().split())
    except ValueError:
        raise Exception("Invalid input. Please provide integers for the array length and target A-characteristic.")

    def recursive_solve(x, m, current_combinations):
        if x >= 2 and current_combinations + math.comb(x, 2) > k:
            return 'NO'
        if m >= 2 and current_combinations + math.comb(m, 2) < k:
            return 'NO'
        if current_combinations == k:
            ones = [1] * x
            minus_ones = [-1] * m
            return ''.join(map(str, ones + minus_ones))

        result = recursive_solve(x+1, m-1, current_combinations)
        if result != 'NO':
            return result

        return recursive_solve(x-1, m+1, current_combinations)

    return recursive_solve(0, n, 0)

