def solve(n, k):
    # Check if n is divisible by 2 or k
    if n % 2 == 0 or n % k == 0:
        return "YES"

    # Check if (n - k) is even or multiple of k
    for x in range(1, math.ceil(n / k)):
        rem = n - k * x
        if rem % 2 == 0 and rem >= 0:
            return "YES"

    return "NO"

