import bisect
from collections import defaultdict

def solve(n, m, P):
    post_time = [-1] * (n + m)
    for t, p in enumerate(P):
        if post_time[p] == -1:
            post_time[p] = t

    ans = [m] * n
    post_idx = {}
    for i in range(n):
        post_idx[i] = i

    new_posts = []
    idx = 0
    while idx < len(post_time[:n]):
        p = post_time[idx]
        if p != -1:
            insert_idx = bisect.bisect_left(new_posts, p)
            if insert_idx == len(new_posts) or new_posts[insert_idx] != p:
                ans[post_idx[idx]] = p
                new_posts.insert(insert_idx, p)
        idx += 1

    return ans

