        num_posts = input().split()

        recent_actions = []
        removal_times = [-2] * len(num_posts)

        for i, post in enumerate(map(int, num_posts)):
            if post not in recent_actions:
                while True:
                    removed_post = None
                    if recent_actions and recent_actions[-1] < post:
                        removed_post = recent_actions.pop()
                    else:
                        break

                    removal_times[removed_post - 1] = i + 1
                    recent_actions.append(post)
