def borders(n, m, x, y):
    if 1 <= x <= n and 1 <= y <= m:
        # Count adjacent accessible cells within maze boundaries
        adjacent_cells = 0
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= n and 1 <= ny <= m:
                adjacent_cells += 1
        return adjacent_cells
    else:
        raise ValueError("Coordinates out of maze boundaries")


