def solve(n, strings):
    pref = [string for string in strings if len(string) == 1 and string[::-1] in strings]

    # Check if there is only one unique single character, which should be the starting character of both prefix and suffix
    if len(pref) != 1:
        return "NO"

    pal = pref[0]
    remaining_chars = n - 2

    # Extend palindrome on both ends as long as possible with existing prefixes and suffixes
    while True:
        extended_palindrome = False

        for s in strings:
            if len(s) == remaining_chars + 1 and (s.startswith(pal) or s.endswith(pal)):
                if s.startswith(pal):
                    new_extension = s[len(pal):]
                else:
                    new_extension = s[:-len(pal)]

                # Check if the extension is of correct length, doesn't repeat in prefixes/suffixes more than twice
                if len(new_extension) == remaining_chars and pref.count(new_extension) < 2: 
                    pal += new_extension if s.startswith(pal) else new_extension + pal
                    extended_palindrome = True
                    break

        # If we cannot extend the palindrome anymore, check its completeness
        if not extended_palindrome:
            return "NO" if len(pal) != n else "YES"

        remaining_chars -= 1

