def solve():
    # Parse input data here (e.g., read from file or standard input)

    move_cmd = input().strip()

    directions = {
        'L': (-1, 0),
        'R': (1, 0),
        'U': (0, 1),
        'D': (0, -1)
    }

    movements = [directions.get(move) for move in move_cmd]

    def update_position(current_pos, movement):
        if movement:
            new_x = current_pos[0] + movement[0]
            new_y = current_pos[1] + movement[1]
            return (new_x, new_y)
        else:
            return current_pos

    positions_traversed = reduce(lambda accum, move: accum + [update_position(accum[-1], move)], movements, [(0, 0)])

    passed_through_target_point = any((x == 1 and y == 1) for (x, y) in positions_traversed) 

    # Output result based on whether Alperen passes through the point (1, 1)

    print("YES" if passed_through_target_point else "NO")

