import functools

def solve(n):
    directions = {
        'U': (0, 1),
        'D': (0, -1),
        'R': (1, 0),
        'L': (-1, 0)
    }

    path_str = input()
    if len(path_str) != n:
        raise ValueError("Path length does not match the given integer")

    position = (0, 0)
    seen_positions = {position}
    for char in path_str:
        direction = directions.get(char.upper())
        if direction is None:
            continue
        position = (position[0] + direction[0], position[1] + direction[1])

        # Check whether the next cell has been visited before.
        seen_positions.add(position)

    # Determine whether Alpern passed by (1, 1).
    return (1, 1) in seen_positions

