        return 'Invalid input: length of string does not match value of n'

    # Correct the simulation by calculating all movements from (0, 0)
    points = [reduce(lambda p1, p2: (p1[0] + p2[0], p1[1] + p2[1]), [(1 if c == 'R' else -1 if c == 'L' else 0, 1 if c == 'U' else -1 if c == 'D' else 0) for c in s[:i+1]]) for i in range(n)]

    # Validate string
    invalid_chars = ''.join(set(s) - {'L', 'R', 'U', 'D'})
    if invalid_chars:
        return f'Invalid input: string contains invalid characters {invalid_chars}'

    points_with_index = [(x, y, idx) for idx, (x, y) in enumerate(points)]
    for (x, y), (_, _, idx2) in itertools.combinations(points_with_index, 2):
      if x == 1 and y == 1 or any((1, 1) == p for p in [reduce(lambda p1, p2: (p1[0] + p2[0], p1[1] + p2[1]), [(1 if c == 'R' else -1 if c == 'L' else 0, 1 if c == 'U' else -1 if c == 'D' else 0) for c in s[i:idx]])) for idx, i in zip(idx2 + 1, range(len(s)))])
        return 'YES'
    return 'NO'

