import sys

def solve():
    n = int(input())
    # Check if n is even
    if n % 2 == 0:
        mid = (n - 1) // 2
        result3 = mid**1 * 1 + 1**mid * mid
        if result3 == n:
            return ' '.join([str(mid), str(1)])

    # Check for x=1 or y=1, and x=n or y=n
    for x in [1, n]:
        y = (n - x**x) / (x + 1)
        if y.is_integer() and 1 <= y <= n:
            return ' '.join([str(x), str(int(y))])

    # If no solution is found, return -1
    return '-1'

