def solve():
    k = int(input())
    def factorial(n):
        if n == 0:
            return 1
        else:
            return functools.reduce(lambda x, y: x * y, range(1, n + 1))

    for i in range(k - 1, 0, -1):
        fact_i = factorial(i)
        fact_i_1 = factorial(i-1) if i > 1 else 1
        total  = fact_i + fact_i_1
        if total % k == 0:
            return i

    return -1

from functools import cmp_to_key

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    key_func = lambda x: -x  # Define a key function that takes one argument
    cmp_func = lambda x, y: (key_func(x) > key_func(y)) - (key_func(x) < key_func(y))
    sorted_a = list(sorted(a[1:], key=cmp_to_key(cmp_func)))
    min_tower_blocks = a[0]

    for tower in sorted_a:
        while min_tower_blocks < tower:
            diff = 1 # we need at least one block
            if (tower - min_tower_blocks + 1) % 2 == 0: # even case: move equal amount of blocks on both side.
                 diff = (tower - min_tower_blocks + 1) // 2 
            else:
                tower -= diff
                break;
            tower -= diff
            min_tower_blocks += diff

    return str(min_tower_blocks)

