import math

def solve(n):
    count = 0
    if len(str(n)) > 2:
        i = 1
        while i < len(str(n))-1:
            count += (9 * (len(str(n))-(i+1)))
            count += (i)*9
            i += 1   
    length = len(str(n))
    total_count = count + int(str(n)[0])*(10**(length-1) - ((10**length)-1)//9)
    # Special case check where first digit of number is greater than the digits following it.
    if n < (int(str(n)[0])*(10**(length-1))):
        total_count = total_count - 1

    return math.floor(total_count)

