def solve():
    n = int(input())
    S = list(map(int, input().split()))

    max_s_1 = max(S)
    if all(s == max_s_1 for s in S):
        return ' '.join(['0'] * n)

    elif len(set([s for s in S if s != max_s_1])) == 1:
        max_s_2 = max([s for s in S if s != max_s_1])
        result = []
        for s in S:
            if s == max_s_1:
                result.append(s - max_s_2)
            else:
                result.append("0")
        return ' '.join(map(str, result))

    else:    
        max_s_2 = sorted(set([s for s in S if s != max_s_1]))[-1]
        result = []
        for s in S:
            if s == max_s_1:
                result.append(s - max_s_2)
            else:
                result.append(s - max_s_1)

        return ' '.join(map(str, result))


