def solve(n, q, a, queries):
    odd_count = sum(1 for x in a if x % 2 != 0)
    even_count = n - odd_count

    result = []
    for type_x, val in queries:
        if (type_x == 0 and val % 2 == 0) or (type_x == 1 and val % 2 != 0):
            increment = even_count
        else:
            increment = odd_count

