from itertools import groupby

def solve():
    a, b = input().split()

    def size_rank(size):
        return ('S', 'M', 'L').index(size[-1])

    def x_count_rank(size):
        g = next(groupby(size), None)
        if g and g[0] == 'X':
            count = len(list(g))
            return -count if size[-1] == 'S' else count
        return 0

    size_a, size_b = size_rank(a), size_rank(b)

    if size_a < size_b:
        return '<'
    elif size_a > size_b:
        return '>'
    else:
        x_count_a, x_count_b = x_count_rank(a), x_count_rank(b)

        if size_a == 0: # Small
            return '>' if x_count_a > x_count_b else ('<' if x_count_a < x_count_b else '=')
        elif size_a == 2: # Large
            return '<' if x_count_a < x_count_b else ('>' if x_count_a > x_count_b else '=')

from functools import cmp_to_key

def solve(a, b):
    vals = {'M': 0, 'S': float('-inf'), 'L': float('inf')}
    def v(x):
        return vals[x[-1]] + len(x) * (x[-1] == 'X') - len(x) * (x[-1] == 'S')

    def compare(x, y):
        if v(x) < v(y):
            return '<'
        elif v(x) > v(y):
            return '>'
        else:
            return '='

    return compare(a, b)

