import math

def sieve_of_eratosthenes(limit):
    """Calculate primes using the Sieve of Eratosthenes method."""
    sieve = [True] * (limit+1)
    for x in range(2, int(math.sqrt(limit)) + 1):
        if sieve[x]: 
            for i in range(x*x, limit+1, x): 
                sieve[i] = False
    return [x for x in range(2, limit) if sieve[x]]

def solve():
    """Return a prime number that when added to input, results in non-prime."""
    primes = sieve_of_eratosthenes(10**5+1)
    return next((prime for prime in reversed(primes[:primes.index(int(input()))]) if not any((int(input()) + prime) % p == 0 for p in primes)), None)

