from collections import defaultdict

def solve(words):
    count = defaultdict(int)
    for i, player in enumerate(words):
        for word in player:
            count[word] += 1

    scores = [0]*3
    for word, freq in count.items():
        for i, player in enumerate(words):
            if word in player:
                if freq == 1:
                    scores[i] += 3
                elif freq == 2:
                    scores[i] += 1
    return ' '.join(map(str, scores))

def solve(n, words_list1, words_list2, words_list3):
    if n <= 0:
        return "Invalid input: n must be a positive integer."

    scores = [0, 0, 0]
    counter = {i: {} for i in range(3)}

    lists = [words_list1, words_list2, words_list3]

    for i, lst in enumerate(lists):
        for word in lst:
            if word not in counter[i]:
                counter[i][word] = 1
            else:
                counter[i][word] += 1

    # Calculate scores
    for i, cnt in enumerate(counter.values()):
        for word, freq in cnt.items():
            total_freq = sum(1 for j in range(3) if word in counter[j])
            if total_freq == 1:
                scores[i] += 3
            elif total_freq > 1 and freq == 1:
                scores[i] += 1

    return ' '.join(map(str, scores))

