import sys

def solve(n, m):
    def count_set_bits(num):
        cnt = 0
        while num > 0:
            if (num & 1) != 0:
                cnt += 1
            else:
                break
            num >>= 1
        return cnt

    nn = count_set_bits(n)
    mm = count_set_bits(m)

    xor_sum = nn ^ mm

    if (xor_sum == 0):
        return "Tonya"
    else:
        return "Burenka"

