import functools
import sys

@functools.lru_cache(maxsize=None)
def mex(start, end):
    seen = set()
    i = start
    while i <= end:
        seen.add(i)
        i += 2
    i = 0
    while True:
        if i not in seen:
            return i
        i += 2

def xor_mex(n, m):
    return "Burenka" if (mex(0, n-1) ^ mex(0, m-1)) != 0 else "Tonya"

