def solve():
    from itertools import accumulate

    s = int(input())
    digits = list(range(9, 0, -1))
    cumsums = list(accumulate(digits))

    ans = ''.join(str(d) for d in chain(*[(x,) if cumsum == s else () 
                                         for x, cumsum in zip(digits, cumsums)]))

    idx = sum(map(int, ans)) if ans else 0

    while idx < s:
        for digit in digits[::-1]:
            if int(''.join(map(str, [digit] + list(ans)))) > idx and digit not in ans:
                return ''.join(map(str, [digit] + list(ans)))

    return str(s)

