def solve() -> int:
    """Find the length of the prefix that needs to be removed from the list"""

    n: int = int(input())  # number of elements in the list
    s: str = input()       # string representation of the list

    unique_nums: set[int] = set()
    has_duplicates: bool = False

    for i, num in enumerate(s.split()):
        if num not in unique_nums:
            unique_nums.add(num)
        else:
            has_duplicates = True
            break

    prefix_length: int = 0
    if has_duplicates:
        # The length of the prefix to be removed is equal to the length of 
        # all elements up to the index where a duplicate was first found.
        for i, num in enumerate(s.split()):
            if num not in unique_nums:
                unique_nums.add(num)
                prefix_length += 1
            else: 
                break

    return len(unique_nums)

