import bisect

def solve():
    try:
        # Using list comprehension and map() for input readability 
        n, k = map(int, input('Enter space-separated values for (n, k): ').split())

        if not isinstance(n, int) or not isinstance(k, int):
            raise ValueError

        arr_input = input("Enter the permutation sequence: ")
        try:
            # map() function to transform inputs into integers to match problem domain
            arr = list(map(int, arr_input.split()))
        except ValueError as e:
            print(f"Error while converting input - {e}")
            return

        if len(arr) != n:
            raise IndexError

        count = 0
        for i in range(k):
            # Check that variable fits into problem domain as per conditions specified by task problem description.
            # arr value is within a given permutation of length 'n' in arbitrary order (1 to n).
            if not (arr[i].is_integer() and 
                    arr[i] > 0 and
                    arr[i] <= len(arr)):
                raise ValueError    

            if arr[i] > k:
                index = bisect.bisect_left(arr, k) - 1
                # Looping until proper position of number k located using binary-search for O(log n)
                while index > i and arr[index] <= k:
                    t = arr[index]
                    arr[index] = arr[i]
                    arr[i] = t
                    count += 1
                    index -= 1

    except ValueError as e:
        print("An error occurred: invalid values entered.")
    except IndexError as ie:
        print(f"Index Error - {ie}")
    else:
        return count

