def solve():
    n, m = map(int, input().split())
    s = ['B'] * m

    def flip(i):
        if i < m // 2 or (i == m // 2 and m % 2):
            j = min(i, m - i - 1)
            return 'A' if s[j] == 'B' else 'B'
        else:
            j = max(i, m - i - 1)
            t = flip(m - i - 1)
            return 'A' if (t == 'B' and s[i] == 'B') or (t != s[i]) else 'B'

    for _ in range(n):
        i = int(input())
        next_state = flip(i)
        j = min(i, m - i - 1)
        if s[j] != 'A' and next_state != 'A':
            s[j] = 'A'

    print(''.join(s))

def solve():
    def recursive(n, x, a):
        if len(a) <= 1:
            return "YES"
        max_val = a.pop()
        min_index = 0
        while min_index < len(a) - 1 and a[min_index + 1] < a[min_index]:
            min_index += 1
        while min_index > 0 and a[0] < a[min_index]:
            min_index -= 1
        if max_val - a[min_index] >= x:
            a.pop(min_index)
            return recursive(n, x, a)
        else:
            return "NO"
    n, x = map(int, input().split())
    a = list(map(int, input().split()))
    return recursive(n, x, sorted(a))

